select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category','f0000000-0000-4000-8000-000000003424')->>'ok','true','unused category deleted');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category','f0000000-0000-4000-8000-000000003424')->>'ok','true','delete replay is safe');
