select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','test_field')->'usage'->>'profiles','1','profile usage explained');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'type','test_type')->>'ok','true','unused custom type deleted');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','test_field')->>'ok','true','unlinked attribute deleted');
