select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'group','f0000000-0000-4000-8000-000000003425')->>'ok','true','unused group deleted');
select throws_ok($$select delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','description')$$,'42501','FORBIDDEN','shared platform attribute protected');
