select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'group',current_setting('test.group'))->>'ok','false','superseded group history still prevents deletion');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'type','trousers')->>'ok','false','superseded type history still prevents deletion');
select set_attribute_definition(current_setting('test.tenant')::uuid,'test_used','{"dataType":"text","labels":{"en":"Used"}}');
select correct_item_attribute(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'test_used','Value','Synthetic correction');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','test_used')->'usage'->>'items','1','attribute correction protects definition');
