select register_purchase(current_setting('test.tenant')::uuid,current_setting('test.purchase')::uuid,'Synthetic purchase',1000,'Synthetic receipt',false);
select set_config('test.owned',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.owned')::uuid,'purchase',current_setting('test.purchase')::uuid,null,2000);
select correct_item_attribute(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.owned')::uuid,'test_used','Value','Synthetic');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','test_used')->'usage'->>'items','2','store-owned items also protect used attribute');
select end_sale_period(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.owned')::uuid,'charity','Synthetic archive');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'attribute','test_used')->'usage'->>'items','2','ended items still protect used attributes');
select set_item_type(current_setting('test.tenant')::uuid,'linked_category','{"labels":{"en":"Category link"},"suggestedCategory":"Böcker"}');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category',current_setting('test.category'))->'usage'->>'profiles','1','translated category linked by type is counted');
select set_config('test.other',create_tenant('Other catalogue','catalogue-other',gen_random_uuid())::text,true);
select is(delete_catalogue_record(current_setting('test.other')::uuid,'category',current_setting('test.category'))->>'ok','true','foreign key is treated as absent in own store');
select is((select count(*) from item_categories where tenant_id=current_setting('test.tenant')::uuid and id=current_setting('test.category')::uuid),1::bigint,'foreign category remains intact');
select throws_ok($$select delete_catalogue_record(current_setting('test.tenant')::uuid,'seller','test')$$,'P0001','INVALID_INPUT','unsupported record types refused');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000003422","role":"authenticated"}';
select throws_ok($$select delete_catalogue_record(current_setting('test.tenant')::uuid,'type','trousers')$$,'42501','FORBIDDEN','cross-store deletion denied');
select is((select count(*) from item_categories where tenant_id=current_setting('test.tenant')::uuid),0::bigint,'cross-store RLS hides records');
select ok(not has_function_privilege('anon','public.delete_catalogue_record(uuid,text,text)','execute'),'anonymous deletion denied');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000003422','staff');
